#!/usr/bin/env python3
"""Generate the committed REST contract without contacting services."""
import json
from pathlib import Path
S=lambda x:{'$ref':'#/components/schemas/'+x}
obj=lambda props,req=[]:{'type':'object','properties':props,'required':req,'additionalProperties':False}
st={'type':'string'}; uid={'type':'string','format':'uuid'}; integer={'type':'integer','minimum':0}
schemas={
'Error':obj({'error':obj({'code':st,'message':st,'details':{'type':'object'}},['code','message'])},['error']),
'UploadRequest':obj({'parent_id':uid,'file_id':uid,'name':st,'size_bytes':integer,'content_type':st,'expected_version_id':uid,'expected_metadata_revision':integer,'idempotency_key':st},['name','size_bytes','idempotency_key']),
'UploadSession':obj({'id':uid,'file_id':uid,'operation_id':uid,'status':st,'upload_url':{'type':'string','format':'uri'},'expires_at':{'type':'string','format':'date-time'}},['id','operation_id','status','upload_url']),
'Mutation':obj({'parent_id':uid,'name':st,'expected_metadata_revision':integer,'expected_version_id':uid,'idempotency_key':st},['expected_metadata_revision','idempotency_key']),
'CreateDirectory':obj({'parent_id':uid,'name':st,'idempotency_key':st},['name','idempotency_key']),
'ShareRequest':obj({'file_id':uid,'audience_type':{'enum':['user','group','link']},'audience_id':st,'rights':{'type':'array','items':{'enum':['read','download','preview']}},'version_policy':{'enum':['latest','fixed']},'version_id':uid,'expires_at':{'type':'string','format':'date-time'}},['file_id','audience_type']),
'Feedback':obj({'file_id':uid,'version_id':uid,'artifact_set_id':uid,'category':{'enum':['text','description','missing_page','format','other']},'body':{'type':'string','minLength':1,'maxLength':10000}},['file_id','version_id','category','body']),
'Search':obj({'query':st,'cursor':st,'limit':{'type':'integer','minimum':1,'maximum':100}},['query']),
'Batch':obj({'idempotency_key':st,'items':{'type':'array','maxItems':100,'items':obj({'item_id':st,'command':{'enum':['mkdir','move','rename','delete','restore','reconvert']},'input':{'type':'object'},'depends_on':{'type':'array','items':st}},['item_id','command','input'])}},['idempotency_key','items']),
'Conversion':obj({'version_id':uid,'idempotency_key':st},['idempotency_key']),
'Completeness':obj({'status':{'enum':['ready','partial']},'total_pages':integer,'missing_text_pages':{'type':'array','items':integer},'missing_description_pages':{'type':'array','items':integer},'warnings':{'type':'array','items':st}},['status']),
'File':{'type':'object','properties':{'id':uid,'owner_id':uid,'space_id':uid,'parent_id':uid,'name':st,'path':st,'kind':{'enum':['file','directory']},'lifecycle':{'enum':['active','deleting','trashed','restoring']},'metadata_revision':integer,'current_version_id':uid,'search_artifact_set_id':uid,'size_bytes':integer,'conversion':{'type':'object'}}},
'Operation':{'type':'object','properties':{'id':uid,'file_id':uid,'kind':st,'state':{'enum':['prepared','executing','outcome_unknown','remote_confirmed','committed','failed_confirmed']},'error_code':st,'result_version_id':uid}},
'Preview':obj({'version_id':uid,'pages':{'type':'array','items':obj({'page':integer,'url':st},['page','url'])},'completeness':S('Completeness')},['version_id','pages']),
}
rows=[('GET','/healthz','Health check',None,None),('GET','/v1/me','Identity, quota and explicit review permissions',None,None),('POST','/v1/session','Create interactive session and CSRF token',None,None),('GET','/v1/files','List owned active files',None,None),('POST','/v1/directories','Create native folder','CreateDirectory','Operation'),('GET','/v1/files/{id}','File metadata',None,'File'),('PATCH','/v1/files/{id}/location','Move or rename via native MOVE','Mutation','Operation'),('POST','/v1/uploads','Reserve quota and create controlled tus session','UploadRequest','UploadSession'),('POST','/v1/uploads/{id}/finalize','Verify native completion and commit once',None,None),('GET','/v1/operations/{id}','Read own operation state with matching scope',None,'Operation'),('GET','/v1/files/{id}/versions','List authorized immutable source versions',None,None),('GET','/v1/files/{id}/content','Stream authorized original or fixed version',None,None),('GET','/v1/files/{id}/markdown','Read pinned artifact, maximum64KiB page',None,None),('GET','/v1/artifacts/{id}/assets/{asset}','Authorize referenced asset',None,None),('POST','/v1/files/{id}/conversions','New immutable recipe generation','Conversion',None),('POST','/v1/search','Owned keyword search with DB reauthorization','Search',None),('DELETE','/v1/files/{id}','Business soft-delete, never native DELETE','Mutation','Operation'),('GET','/v1/trash','List retained business trash',None,None),('POST','/v1/trash/{id}/restore','Restore, explicit name conflicts','Mutation','Operation'),('POST','/v1/batches','Persistent independent per-item results','Batch',None),('POST','/v1/share-requests','Immutable pending share details','ShareRequest',None),('GET','/v1/share-requests','List own confirmations',None,None),('GET','/v1/share-requests/{id}','Read own confirmation',None,None),('POST','/v1/share-requests/{id}/approve','Interactive owner confirmation plus CSRF',None,None),('GET','/v1/shares','List own grants, never expose stored link secrets',None,None),('POST','/v1/shares/{id}/revoke','Revoke every later resource request',None,None),('GET','/v1/shared-with-me','Web only, excludes Agent',None,None),('GET','/v1/preview/{id}','Authorized raster preview manifest',None,'Preview'),('GET','/v1/preview/{id}/pages/{page}','Reauthorized raster page',None,None),('GET','/s/{token}','Anonymous raster-only preview page',None,None),('GET','/s/{token}/pages/{page}','Recheck grant, owner and version for every raster',None,None),('POST','/v1/feedback','No identity/source logging or audit','Feedback',None),('GET','/v1/delegation/status','Explicit offline-grant state',None,None),('POST','/v1/delegation/start','Start user-consented background read authorization',None,None),('GET','/v1/delegation/callback','One-time OAuth PKCE callback and encrypted refresh storage',None,None),('GET','/v1/admin/jobs','Explicit processing-review grant required',None,None),('GET','/v1/admin/feedback','Explicit feedback-review grant required',None,None),('GET','/v1/download/{token}','Short-lived original ticket with live authorization',None,None),('HEAD','/v1/tus/{id}','Query native confirmed upload offset',None,None),('PATCH','/v1/tus/{id}','Stream chunk, no whole-file buffering',None,None),('OPTIONS','/v1/tus/{id}','Tus protocol capabilities',None,None)]
rows += [("GET","/v1/audit/files/{id}/versions","Explicit audit grant: retained source versions",None,None),("GET","/v1/audit/files/{id}/content","Explicit audit grant: pinned retained original",None,None),("GET","/v1/audit/files/{id}/markdown","Explicit audit grant: pinned retained Markdown",None,None)]
rows += [("GET","/v1/audit/files/{id}/artifacts/{artifact}/assets/{asset}","Explicit audit grant: exact retained manifest asset",None,None)]
paths={}
import re
for method,path,summary,request,response in rows:
 entry={'summary':summary,'security':[{'bearerAuth':[]}],'parameters':[],'responses':{'200':{'description':'Success','content':{'application/json':{'schema':S(response) if response else {'type':'object'}}}}}}
 for p in re.findall(r'{(.*?)}',path):entry['parameters'].append({'name':p,'in':'path','required':True,'schema':st})
 if method=='GET' and (path.startswith('/v1/files') or path.startswith('/v1/audit/files')):
  for p in ['parent_id','cursor','version_id','artifact_set_id']:entry['parameters'].append({'name':p,'in':'query','schema':st})
 if request:entry['requestBody']={'required':True,'content':{'application/json':{'schema':S(request)}}}
 if '/content' in path or '/download/' in path or '/pages/' in path or '/assets/' in path:entry['responses']['200']['content']={'application/octet-stream':{'schema':{'type':'string','format':'binary'}}};entry['responses']['206']={'description':'Authorized single byte range'}
 if '/tus/' in path:
  for h in ['Tus-Resumable','Upload-Offset','Content-Length']:entry['parameters'].append({'name':h,'in':'header','schema':st})
  if method=='PATCH':entry['requestBody']={'required':True,'content':{'application/offset+octet-stream':{'schema':{'type':'string','format':'binary'}}}};entry['responses']['204']={'description':'Chunk acknowledged; Upload-Offset header is authoritative'}
 if path.endswith('/approve'):
  entry['parameters'] += [{'name':'X-CSRF-Token','in':'header','required':True,'schema':st},{'name':'Origin','in':'header','required':True,'schema':st}]
 if path.startswith('/s/') or path=='/healthz' or path.endswith('/callback') or '/download/' in path:entry['security']=[]
 for status in [401,403,404,409,413,422,429,503]:entry['responses'][str(status)]={'description':'Structured business error','content':{'application/json':{'schema':S('Error')}}}
 paths.setdefault(path,{})[method.lower()]=entry
out={'openapi':'3.1.0','info':{'title':'Agent CloudDrive REST API','version':'0.1.0','description':'Native oCIS interfaces remain private. Historical source/artifact IDs are immutable; anonymous feedback is a separate no-source path. See docs/acceptance.md for actual verified vs pending gates.'},'servers':[{'url':'https://drive.localhost:8080'}],'paths':paths,'components':{'securitySchemes':{'bearerAuth':{'type':'http','scheme':'bearer','bearerFormat':'JWT'}},'schemas':schemas}}
Path('docs/openapi.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
